// Saída do Merge: um item com body.clientes e investimentos
const dados = $input.first().json;
const clientes = dados.body?.clientes ?? [];
const investimentos = dados.investimentos ?? [];

// "R$ 12.500,00" -> 12500
const paraNumero = (valor) =>
  Number(String(valor).replace(/[^\d,]/g, '').replace(',', '.')) || 0;

// 1000 -> "R$ 1.000,00"
const formatarBRL = (n) => {
  const [inteiro, decimal] = Number(n).toFixed(2).split('.');
  return 'R$ ' + inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + decimal;
};

// "12.5%" -> "12,5%"
const formatarRentabilidade = (r) => String(r).replace('.', ',');

return clientes.map((cliente) => {
  const saldo = paraNumero(cliente.saldo);

  // Produtos do mesmo perfil do cliente
  const opcoes = investimentos.filter(
    (inv) => inv.perfil.toLowerCase() === cliente.perfil.toLowerCase()
  );

  // Produtos que o saldo permite, do maior mínimo para o menor
  const acessiveis = opcoes
    .filter((inv) => inv.minimo <= saldo)
    .sort((a, b) => b.minimo - a.minimo);

  let mensagem;
  let produto = null;

  if (acessiveis.length > 0) {
    produto = acessiveis[0];
    mensagem =
      `Olá ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é ` +
      `${produto.produto} (mínimo ${formatarBRL(produto.minimo)}). ` +
      `Com seu saldo atual (${formatarBRL(saldo)}), você já consegue investir. ` +
      `Rentabilidade: ${formatarRentabilidade(produto.rentabilidade)}`;
  } else if (opcoes.length > 0) {
    // O saldo não cobre nenhum produto: sugere o de menor mínimo
    produto = [...opcoes].sort((a, b) => a.minimo - b.minimo)[0];
    const falta = produto.minimo - saldo;
    mensagem =
      `Olá ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é ` +
      `${produto.produto} (mínimo ${formatarBRL(produto.minimo)}). ` +
      `Com seu saldo atual (${formatarBRL(saldo)}), faltam ${formatarBRL(falta)} para investir. ` +
      `Rentabilidade: ${formatarRentabilidade(produto.rentabilidade)}`;
  } else {
    mensagem = `Olá ${cliente.nome}! No momento não temos opções para o perfil ${cliente.perfil}.`;
  }

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      produto: produto?.produto ?? null,
      mensagem,
    },
  };
});

// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];
